const dictionaries = { en, bn, hi } as const;
const dynamic: Partial<Record<LanguageCode,Partial<Record<UiKey,string>>>> = {};
const catalog: Partial<Record<LanguageCode,Record<string,string>>> = {};
export function setInterfaceTranslations(language:LanguageCode,translations:Partial<Record<UiKey,string>>):void {
 dynamic[language]={...dynamic[language],...translations};
}
export function setCatalogTranslations(language:LanguageCode,translations:Record<string,string>):void {catalog[language]={...catalog[language],...translations};}
export function displayText(language:LanguageCode,source:string):string {return catalog[language]?.[source]||source;}
export function translatedKeyCount(language:LanguageCode):number {return Object.keys(dynamic[language]||{}).length;}
export function interfaceLocale(language:LanguageCode):'en'|'bn'|'hi' { return language==='bn'?'bn':language==='hi'?'hi':'en'; }
export function hasInterfaceTranslation(language:LanguageCode):boolean { return language==='en'||language==='bn'||language==='hi'||translatedKeyCount(language)===Object.keys(en).length; }
export function ui(language:LanguageCode,key:UiKey,values:Record<string,string|number>={}):string {
 const text=dynamic[language]?.[key] || dictionaries[interfaceLocale(language)][key];
 return text.replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??`{${name}}`));
}
const UiContext=createContext<LanguageCode>('en');
export function UiProvider({language,children}:{language:LanguageCode;children:React.ReactNode}) {return <UiContext.Provider value={language}>{children}</UiContext.Provider>;}
export function useUi(){const language=useContext(UiContext);return (key:UiKey,values?:Record<string,string|number>)=>ui(language,key,values);}
export function useDisplayText(){const language=useContext(UiContext);return (source:string)=>displayText(language,source);}
